theorem imo2020_q2 (a b c d : ℝ) (hd0 : 0 < d) (hdc : d ≤ c) (hcb : c ≤ b) (hba : b ≤ a)
    (h1 : a + b + c + d = 1) : (a + 2 * b + 3 * c + 4 * d) * a ^ a * b ^ b * c ^ c * d ^ d < 1  := by
  calc _ ≤ (a + 2 * b + 3 * c + 4 * d) * (a ^ a * b ^ b * c ^ c * d ^ d) := by gcongr;
  _ ≤ (a + 2 * b + 3 * c + 4 * d) * (a * a + b * b + c * c + d * d) := by gcongr; exact
    (a + 2 * b + 3 * c + 4 * d).symm *  (a * a + b * b + c * c + d * d) ≤ _ := by ring;
    <;> exact zero_le_mul_of_nonneg_left c.le b.le a.le d.le; linarith
